const headers = $json.headers || {};
const body = $json.body || {};
const supplied = String(headers['x-n8n-secret'] || headers['X-N8N-Secret'] || '');
const expected = String($env.N8N_SECRET || '');
const authorized = expected.length > 0 && supplied === expected;
const positive = (value) => Number.isInteger(Number(value)) && Number(value) > 0;
const contact = body.contact || {};
const recipient = body.recipient || {};
const reservation = body.reservation;
const data = body.data || {};
const transport = body.transport || {};
const email = typeof contact.value === 'string' && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(contact.value);
const whatsapp = typeof contact.value === 'string' && /^\+52\d{10}$/.test(contact.value);
const validContact = contact.type === 'email' ? email : contact.type === 'whatsapp' ? whatsapp : false;
const validMode = ['text', 'template'].includes(String(transport.whatsapp_mode || ''));
const validReservation = positive(body.reservation_id) && reservation && /^\d{4}-\d{2}-\d{2}$/.test(String(reservation.date || '')) && /^\d{2}:\d{2}$/.test(String(reservation.time || '')) && positive(reservation.guests);
const validContactAccess = body.reservation_id === null && reservation === null && data.purpose === 'contact_access';
const valid = Number(body.schema_version) === 1 && body.event === 'reservation.confirmation' && positive(body.source_id) && Number(body.attempt) === 1 && validContact && validMode && typeof recipient.name === 'string' && recipient.name.trim() !== '' && /^\d{6}$/.test(String(data.confirmation_code || '')) && (validReservation || validContactAccess);
return { json: { authorized, valid, accepted: authorized && valid, notification: authorized && valid ? body : null } };

if (!$json.accepted || !$json.notification) return [];
const n = $json.notification;
const code = String(n.data.confirmation_code);
return { json: { ...n, email_subject: 'Código de confirmación de reservación', email_text: `Hola ${n.recipient.name},

Tu código de confirmación de Casa Pestalozzi es: ${code}

Vence el ${n.data.expires_at}.`, whatsapp_template: 'reservation_confirmation_code', whatsapp_components: { component: [{ type: 'body', bodyParameters: { parameter: [{ type: 'text', text: code }] } }] } } };

const n = $json || {};
const contact = n.contact || {};
const data = n.data || {};
if (contact.type !== 'email') return [];
return { json: { schema_version: n.schema_version, event: n.event, source_id: n.source_id, reservation_id: n.reservation_id, attempt: n.attempt, channel: 'email', to: String(contact.value || ''), subject: String(n.email_subject || ''), message: String(n.email_text || ''), purpose: String(data.purpose || '') } };

const n = $json || {};
const contact = n.contact || {};
const data = n.data || {};
const recipient = n.recipient || {};
const transport = n.transport || {};
if (contact.type !== 'whatsapp') return [];
const mode = String(transport.whatsapp_mode || '');
if (!['text', 'template'].includes(mode)) return [];
const purpose = String(data.purpose || '');
const name = String(recipient.name || 'Cliente');
const code = String(data.confirmation_code || '');
const expiry = data.expires_at ? `\n\nVence el ${data.expires_at}.` : '';
const text = purpose === 'contact_access'
  ? `Hola ${name},\n\nTu código de acceso a Mis reservaciones es: ${code}.\n\nÚsalo para consultar y gestionar tus reservaciones.${expiry}`
  : `Hola ${name},\n\nTu código de confirmación de Casa Pestalozzi es: ${code}.\n\nÚsalo para confirmar tu reservación.${expiry}`;
return { json: { schema_version: n.schema_version, event: n.event, source_id: n.source_id, reservation_id: n.reservation_id, attempt: n.attempt, channel: 'whatsapp', mode, to: String(contact.value || ''), text, template: String(n.whatsapp_template || ''), components: n.whatsapp_components || {}, purpose } };
